/**
 * APPLY COMPREHENSIVE FIXES
 * 
 * This applies the fixes generated by comprehensive-fix.js
 * but preserves original gender_category for Kids products
 */

const fs = require('fs');
const path = require('path');

const envContent = fs.readFileSync(path.join(__dirname, '..', '.env.local'), 'utf8');
const env = {};
envContent.split('\n').forEach(line => {
  const m = line.match(/^([^=]+)=(.*)$/);
  if (m) env[m[1].trim()] = m[2].trim();
});

const DIRECTUS_URL = 'https://zecode-directus.onrender.com';

async function applyFixes() {
  const authRes = await fetch(DIRECTUS_URL + '/auth/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: 'zecode@siyaram.com', password: env.DIRECTUS_ADMIN_PASSWORD })
  });
  const token = (await authRes.json()).data.access_token;
  
  // Get current products to preserve kids info
  const res = await fetch(DIRECTUS_URL + '/items/products?limit=-1', {
    headers: { 'Authorization': 'Bearer ' + token }
  });
  const currentProducts = (await res.json()).data;
  const productMap = {};
  currentProducts.forEach(p => productMap[p.id] = p);
  
  // Load fixes
  const fixes = JSON.parse(fs.readFileSync('comprehensive-fixes.json', 'utf8'));
  
  console.log(`Applying ${fixes.length} fixes...`);
  
  let updated = 0;
  let failed = 0;
  
  for (const fix of fixes) {
    const original = productMap[fix.id];
    
    // Preserve kids category - use original data if it was kids
    let genderCategory = fix.new.gender_category;
    let gender = fix.new.gender;
    let category = fix.new.category;
    let name = fix.new.name;
    
    if (original.gender_category === 'Kids' || original.category === 'Kids') {
      genderCategory = 'Kids';
      category = 'Kids';
      gender = original.gender; // Keep original Boy/Girl
      
      // Fix the name prefix for kids
      const genderPrefix = original.gender === 'Girl' ? "Girl's" : "Boy's";
      name = fix.new.name
        .replace(/^Women's /, genderPrefix + ' ')
        .replace(/^Men's /, genderPrefix + ' ');
    }
    
    const slug = name.toLowerCase()
      .replace(/['']/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '');
    
    // Update description to match the correct name
    let description = fix.new.description;
    
    const updateData = {
      name: name,
      slug: slug,
      description: description,
      color: fix.new.color,
      pattern: fix.new.pattern,
      style: fix.new.style,
      subcategory: fix.new.subcategory,
      category: category,
      gender: gender,
      gender_category: genderCategory
    };
    
    try {
      const updateRes = await fetch(`${DIRECTUS_URL}/items/products/${fix.id}`, {
        method: 'PATCH',
        headers: {
          'Authorization': 'Bearer ' + token,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(updateData)
      });
      
      if (updateRes.ok) {
        updated++;
        if (updated % 25 === 0) {
          console.log(`Progress: ${updated}/${fixes.length}`);
        }
      } else {
        failed++;
        console.error(`Failed ID ${fix.id}:`, await updateRes.text());
      }
    } catch (err) {
      failed++;
      console.error(`Error ID ${fix.id}:`, err.message);
    }
  }
  
  console.log(`\n=== COMPLETE ===`);
  console.log(`Updated: ${updated}`);
  console.log(`Failed: ${failed}`);
}

applyFixes().catch(console.error);
